def choose(devices, target):
    chosen, total = [], 0.0
    for name in sorted(devices, key=lambda n: (-devices[n], n)):
        if total >= target:
            break
        chosen.append(name)
        total += devices[name]
    return chosen, round(total, 1)

def tier(device):
    os_major = device['os_major']
    if os_major < device['min_supported_os']:
        raise ValueError('unsupported OS')
    if (device['share'] >= 10 or os_major == device['min_supported_os']
            or os_major == device['latest_os'] or device.get('key_customer', False)):
        return 1
    if device['share'] >= 3:
        return 2
    return 3
